/**
 * Generic pincode → constituency lookup covering every wired state.
 *
 * The maps are GENERATED by `pipeline/pincode_map.py` (polygon overlap of
 * pincode boundaries against assembly-constituency boundaries) and shipped as
 * one lazy JSON chunk per state — `src/data/<state>/pincodes.json`, loaded on
 * demand via the 3-digit-prefix index. A pincode can legitimately straddle
 * constituencies, so a lookup returns 1–3 candidate constituency ids, the
 * dominant one first; the UI shows a picker when there's more than one.
 *
 * The older hand-verified map (pincode-map.ts) acts as a fallback for
 * pincodes the generated data doesn't cover.
 */

import prefixIndex from './pincode-index.json'
import { lookupPincode as curatedLookup } from './pincode-map'

export interface PincodeMatch {
  stateId: string
  /** 1–3 constituency ids, dominant (largest area overlap) first. */
  constituencyIds: string[]
}

/** stateId -> directory name under src/data (mostly identical). */
const STATE_DIRS: Record<string, string> = {
  'arunachal-pradesh': 'arunachal',
  'himachal-pradesh': 'himachal',
  'uttar-pradesh': 'up',
  'tamil-nadu': 'tamilnadu',
  'west-bengal': 'westbengal',
  'madhya-pradesh': 'madhyapradesh',
  'andhra-pradesh': 'andhrapradesh',
  'jammu-kashmir': 'jammukashmir',
}

const chunkLoaders = import.meta.glob<{ default: Record<string, string[]> }>(
  './*/pincodes.json',
)

const loadedChunks = new Map<string, Promise<Record<string, string[]>>>()

function loadStateChunk(stateId: string): Promise<Record<string, string[]>> {
  let p = loadedChunks.get(stateId)
  if (!p) {
    const dir = STATE_DIRS[stateId] ?? stateId
    const loader = chunkLoaders[`./${dir}/pincodes.json`]
    p = loader ? loader().then((m) => m.default) : Promise.resolve({})
    loadedChunks.set(stateId, p)
  }
  return p
}

export async function lookupPincodeAnywhere(
  pincode: string,
): Promise<PincodeMatch | undefined> {
  const states = (prefixIndex as Record<string, string[]>)[pincode.slice(0, 3)]
  if (states) {
    for (const stateId of states) {
      const chunk = await loadStateChunk(stateId)
      const ids = chunk[pincode]
      if (ids?.length) return { stateId, constituencyIds: ids }
    }
  }
  // Fall back to the hand-verified map for anything the generated data lacks.
  const curated = curatedLookup(pincode)
  if (curated) {
    return { stateId: curated.stateId, constituencyIds: [curated.constituencyId] }
  }
  return undefined
}
